  "target_groups": [
    "Kuvitteellisten tekstiilipajojen työntekijät",
    "Epävarma kierrätysalan toimijoiden ja kuluttajien ryhmä"
  ],
  "preliminary_activities": [
    {
      "id": "A1",
      "description": "Koota leikkuujätteet viidestä paja-alueesta yhteiseen varastoon.","objective_ids": ["O1"]
    },
    {
      "id": "A2",
      "description": "Testata eri materiaalien lajittelua ja uudelleenkäyttöprosessia pilotin aikana.","objective_ids": ["O1", "O2"]
    },
    {
      "id": "A3",
      "description": "Laskella kustannukset ja arvioida turvallisuusriskit jokaisessa materiaalivirrassa.","objective_ids": ["O2"]
    }
  ],
  "expected_results": [
    {
      "id": "R1",
      "description": "Määritellään yhteiset lajittelun tekniset standardit.","activity_ids": ["A1", "A2"]}
    ],
    "proposed_indicators": [
    {
      "id": "I1",
      "description": "Lajittelun tehokkuus määritellään.","result_ids": ["R1"],
      "measurement_method": "Mittari lasketaan oikein lajitteluksia jaettuna kokonaislajitteluksilla, yksikkö on kpl, osoitettavaa kriteeriä on lajittelun tarkkuus, menetelmä on manuaalinen tai automaattinen laskenta, ajoitus on kuukausi 1-3."
    },
    {
      "id": "I2",
      "description": "Uudelleenkäytön turvallisuus ja taloudellisuus osoitetaan.","result_ids": ["R2"],
      "measurement_method": "Mittari lasketaan turvallisesti uudelleenkäytettyjen materiaalien määrä jaettuna kustannuksiin, yksikkö on kpl/EUR, osoitettavaa kriteeriä on nettohyöty tai turvallisuusvaatimusten täyttäminen, menetelmä on taloudellinen analyysi ja turvallisuuskatselmoitukset, ajoitus on kuukausi 4-9."
    }
  ],
  "assumptions": [
    "Materiaalien laatu on ennustettavissa olevaa vaihtelua pajojen välillä.",
    "Kustannuslaskelmat ovat epävarmia ilman lähtötietoja.",
    "Turvallisuusvaatimukset voivat poistaa tietyt materiaalit käytöstä."
  ],
  "open_questions": [
    "Materiaalien lajittelun tekniset standardit on vielä määritettävä.",
    "Uudelleenkäytön markkinointikanavat ja hyötykäyttöryhmän määrittely ovat epävarmat.",
    "Pilotin jatkaminen tai muuttaminen riippuu kustannusten ylittymisestä odotuksista."
  ]
}

{
  "findings": [
    {
      "reference": "O2, I2",
      "observation": "Indikaattori I2 viittaa tulokseen R2, joka ei ole määritelty konseptissa.",
      "evidence_quote": "\"result_ids\": [\"R2\"]","severity": "major"
    },
    {
      "reference": "A3",
      "observation": "Toiminta A3 on liitetty vain tavoitteeseen O2, mutta se ei ole osa odotettua tulosta R1.",
      "evidence_quote": "\"activity_ids\": [\"A1\", \"A2\"]","severity": "minor"
    },
    {
      "reference": "I1",
      "observation": "Indikaattorin mittausmenetelmä on epäselvä ja logiikkaan ristiriidassa (lasketaan lajitteluja, osoitettava tarkkuus).",
      "evidence_quote": "\"measurement_method\": \"Mittari lasketaan oikein lajitteluksia...\"","severity": "question"
    },
    {
      "reference": "Funding_context",
      "observation": "Alkuperäisessä ideassa ei ole lähtötietoja kustannuksista, mutta ehdotus vaatii kustannuslaskelmien tekemisen ilman perustietoa.",
      "evidence_quote": "\"funding_context\":null","severity": "question"
    }
  ],
  "suggested_improvements": [
    "Määritellä tulokseksi R2 tai poistaa viittaus I2:stä, jotta indikaattori on referenssiin sidottu.",
    "Liittää toiminta A3 odotettuun tulokseen (esim. uudeksi R2:ksi) tai määritellä sen oman tuloksen.",
    "Selventää indikaattorin I1 mittausmenetelmän logiikkaa ja yksikön määrittelyä.",
    "Tarkistaa, onko kustannuslaskelmissa riittävä tieto tai lisätä oletukset selkeästi."
  ]
}

